namespace sarif.handlers.result;



using com.contrastsecurity.sarif;

using db;
using ghidra.program.model.address;
using sarif.handlers;
using sarif.model;
using sarif.model;

public class SarifPropertyResultHandler : SarifResultHandler {

	/* @Override */
	public string getKey() {
		return "Property";
	}

	/* @Override */
	public List<Address> parse() {
		return controller.getListingAddresses(run, result);
	}

	/* @Override */
	public void handle(SarifDataFrame dframe, Run run, Result result, Map<string, object> map) {
		this.controller = dframe.getController();
		List<SarifColumnKey> columns = dframe.getColumns();
		List<string> columnNames = new();
		foreach (SarifColumnKey c in columns) {
			columnNames.add(c.getName());
		}
		PropertyBag properties = result.getProperties();
		if (properties == null) {
			return;
		}
		Map<string, object> additional = properties.getAdditionalProperties();
		if (additional == null) {
			return;
		}
		using (Transaction t = controller.getProgram().openTransaction("SARIF custom properties."))
{
			foreach (string key in additional.keySet()) {
				string[] splits = key.split("/");
				switch (splits[0]) {
					case "viewer":
						switch (splits[1]) {
							case "table":
								if (!columnNames.contains(splits[2])) {
									columns.add(new SarifColumnKey(splits[2], false));
								}
								map.put(splits[2], additional.get(key));
						}
						break;
					case "listing":
						controller.handleListingAction(run, result, splits[1], additional.get(key));
						break;
				}
			}
			t.commit();
		}
	}
}
